for year, raws in c12ts_data.items():
    for raw in raws:
        v = clean_c12(raw)
        if v and 'TOURING' in v.upper():
            add(c12ts, year, v, 'hybride')
        elif v:
            add(corolla, year, v, 'hybride')

def year_total(model):
    return sum(len(vs) for k,v in model.items() if isinstance(v,dict) for vs in v.values())

print(f"Corolla: {sorted(k for k in corolla if k.isdigit())} → {year_total(corolla)} versions")
